// Generated by tools/gen-protocol.ts from crates/protocol/schema.json, which crates/protocol-schema
// exports from the Rust types in crates/protocol.
// Do not edit: run `make protocol` after changing the Rust types.
//
// Bus frames are a 4-byte big-endian length followed by one UTF-8 JSON `Message`.
//
// Integers are 64-bit on the wire; ids and counts stay well below 2^53.

/**
 * The broker's own name: `hello`, `claim`, `release` and `list` go to it, and `adopt`, with which
 * session hands it connections for services and apps.
 */
export const BROKER = "bus";

/**
 * How long the broker waits for a response before answering `timeout` itself, unless the request
 * sets `timeout_ms`.
 */
export const DEFAULT_TIMEOUT_MS = 30000;

/** Most file descriptors one message may carry. */
export const MAX_FDS_PER_MESSAGE = 16;

/** Largest frame the broker accepts, not counting the 4-byte length prefix. */
export const MAX_FRAME_BYTES = 4194304;

/** The broker's trace of every message; only trusted connections may subscribe. */
export const TAP_TOPIC = "bus.tap";

/** Error codes the broker itself sends. Services may send their own. */
export type BrokerErrorCode =
  /** The frame was valid JSON but the message makes no sense (unknown method, bad params). */
  | "bad_request"
  /** No connection has claimed the name the request was sent to. */
  | "no_such_service"
  /** Another connection already holds the name. */
  | "name_taken"
  /** The permission hook refused the message. */
  | "permission_denied"
  /** The service didn't answer within the request's timeout. */
  | "timeout"
  /** The service disconnected before answering. */
  | "service_gone";

/** Why a request failed. `code` is one of the broker's codes or a service's own. */
export type BusError = { code: string; message: string };

/** Params of a `compositor.commit` request. */
export type Commit = { window: number; ops: SceneOp[] };

/** One bus frame's JSON. */
export type Message =
  | {
    kind: "request";
    id: number;
    to: string;
    method: string;
    /** How many file descriptors travel with this message (see `unix`). */
    fds?: number;
    from?: Sender | null;
    params?: unknown;
    /** Overrides `DEFAULT_TIMEOUT_MS`. */
    timeout_ms?: number | null;
  }
  | {
    kind: "response";
    id: number;
    ok: boolean;
    error?: BusError | null;
    fds?: number;
    result?: unknown;
  }
  /**
   * The requester no longer wants the answer to request `id`. The broker
   * forwards it to the service and drops the response if one still comes.
   */
  | { kind: "cancel"; id: number }
  /**
   * `topic` is an exact topic, or a prefix ending in `.*` (see
   * `topic_matches`). The broker answers with a response carrying `id`.
   */
  | { kind: "subscribe"; id: number; topic: string }
  | { kind: "unsubscribe"; id: number; topic: string }
  | { kind: "publish"; topic: string; data?: unknown; fds?: number; from?: Sender | null };

/**
 * Node types understood by the compositor. Phase 0 renders the primitives
 * (`rect`, `text`, `group`); widgets arrive in M4 and M5.
 */
export type NodeKind = "group" | "rect" | "text" | "image" | "vstack" | "hstack" | "label" | "button";

/** One change to a window's scene graph. */
export type SceneOp =
  | { op: "create"; id: number; type: NodeKind; props?: Record<string, unknown> }
  /** Merge `props` into the node's existing props. */
  | { op: "set"; id: number; props: Record<string, unknown> }
  | { op: "insert"; parent: number; child: number; index: number }
  | { op: "remove"; parent: number; child: number }
  | { op: "destroy"; id: number }
  | { op: "listen"; id: number; events: string[] };

/** Who sent a message, as stamped by the broker. */
export type Sender =
  /** A system service that claimed a well-known name such as `db`. */
  | { service: string }
  /** An app, identified by its app id and bus connection number. */
  | { app: { app: string; conn: number } }
  /**
   * A trusted local connection (a tool such as `osctl`, or a service before it
   * claims a name), identified by its bus connection number.
   */
  | { conn: number };
